//
// Test of mgc_conv_im2col_opt, generated by mgc from conv_im2col_opt.mgc: do not edit, re-run
// mgc/mgcc.py.

#include <stdint.h>

#include "mgc_conv_im2col_opt.h"
#include "test.h"

#include "tile.h"
#include "mg_fsync.h"

int main(void)
{
    uint32_t hartid = get_hartid();

    mgc_conv_im2col_opt(x_inp,
                        w_inp,
                        y_out,
                        CONV_H,
                        CONV_W,
                        CONV_CIN,
                        CONV_COUT,
                        CONV_K,
                        CONV_PAD,
                        CONV_S,
                        CONV_OH,
                        CONV_OW,
                        CONV_ROW,
                        CONV_KKC,
                        CONV_HW,
                        CONV_CP,
                        CONV_NB,
                        CONV_CB,
                        CONV_WNB,
                        CONV_WB,
                        CONV_WIN,
                        CONV_SHARE_CHUNK);

    /* once every tile has finished, each tile checks its share of the rows */
    mg_fsync_init();
    mg_fsync_global(WFE);

    uint32_t share  = (CONV_HW + NUM_HARTS - 1) / NUM_HARTS;
    uint32_t r_end  = (hartid + 1) * share < CONV_HW ? (hartid + 1) * share : CONV_HW;
    uint32_t errors = 0;
    uint16_t computed, expected, diff;
    for (uint32_t i = hartid * share; i < r_end; i++) {
        for (uint32_t j = 0; j < CONV_COUT; j++) {
            computed = *(volatile uint16_t *)(y_out + (i * CONV_COUT + j));
            expected = *(volatile uint16_t *)(y_gold + (i * CONV_COUT + j));
            diff     = (computed > expected) ? (computed - expected) : (expected - computed);
            if (diff > 0x0011) {
#if EVAL == 1
                printf("Error detected at coordinates[%d][%d]: y_out=%x y_gold=%x\n",
                       i,
                       j,
                       *(volatile uint16_t *)(y_out + (i * CONV_COUT + j)),
                       *(volatile uint16_t *)(y_gold + (i * CONV_COUT + j)));
#endif
                errors++;
            }
        }
    }
    printf("TILE %d: Number of errors: %d\n", hartid, errors);

    return errors;
}
